{
  "name": "@martsallan/goal-opencode",
  "version": "0.3.1",
  "type": "module",
  "description": "Long-running goal mode for OpenCode with auto-continuation, auto-clear on completion, and a goal sidebar widget",
  "main": "./src/index.ts",
  "exports": {
    ".": "./src/index.ts",
    "./tui": "./src/tui.tsx"
  },
  "files": [
    "src",
    "!src/**/*.test.ts",
    "README.md",
    "CHANGELOG.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "goal",
    "sidebar",
    "tui"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/martsallan/goal-opencode.git"
  },
  "homepage": "https://github.com/martsallan/goal-opencode#readme",
  "bugs": {
    "url": "https://github.com/martsallan/goal-opencode/issues"
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "bun test"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.17.3",
    "@opencode-ai/sdk": "^1.17.3"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.3.4",
    "@opentui/keymap": ">=0.3.4",
    "@opentui/solid": ">=0.3.4",
    "solid-js": "^1.9.12"
  },
  "devDependencies": {
    "@opentui/core": "0.4.0",
    "@opentui/keymap": "0.4.0",
    "@opentui/solid": "0.4.0",
    "@types/bun": "^1.3.14",
    "@types/node": "^25.8.0",
    "solid-js": "1.9.12",
    "typescript": "^5.9.3"
  }
}
